-- City sweep group 15 (Southwest Riverside & the Pass), 2026-10-25 — fifth pass.
-- Adds events not covered by 0015–0018. Geocoding services were unreachable in this run:
-- lat/lng are venue-level estimates from the street address (not city centers) and should be spot-checked.
ON CONFLICT(id) DO UPDATE SET name=excluded.name, county=excluded.county, city=excluded.city, type=excluded.type, start_date=excluded.start_date, end_date=excluded.end_date, status=excluded.status, free=excluded.free, price=excluded.price, hours=excluded.hours, lat=excluded.lat, lng=excluded.lng, blurb=excluded.blurb, url=excluded.url, season=excluded.season, venue=excluded.venue, address=excluded.address, updated_at=datetime('now');

-- Old Town Temecula's calendar lists A Very Temecula Christmas for Dec 10–12, 2026
UPDATE events SET status='confirmed', start_date='2026-12-10', end_date='2026-12-12', hours='Daily events Dec 10–12; Santa Under the Tree at the Civic Center Sat Dec 12, 1–4pm',
  updated_at=datetime('now') WHERE id='g15-very-merry-temecula-christmas';
